220: static void IRAM_ATTR esp_mipi_dsi_dma_restart(
221:     FAR struct esp_mipi_dsi_priv_s *priv)
222: {
223:   FAR dw_gdma_dev_t *dev = priv->dw_hal.dev;
224:   FAR dw_gdma_link_list_item_t *lli_nc = priv->lli_nc;
225: 
226:   if (dev == NULL || lli_nc == NULL || priv->lli == NULL)
227:     {
228:       return;
229:     }
230: 
231:   /* Re-arm via NC alias (ESP-IDF mipi_dsi_dma_trans_done_cb). */
232: 
233:   dw_gdma_ll_lli_set_block_markers(lli_nc, false, true, true);
234:   dw_gdma_ll_channel_set_link_list_master_port(dev, ESP_MIPI_DSI_DMA_CHAN,
235:                                               DW_GDMA_LL_MASTER_PORT_MEMORY);
236:   dw_gdma_ll_channel_set_link_list_head_addr(dev, ESP_MIPI_DSI_DMA_CHAN,
237:                                              (uint32_t)(uintptr_t)priv->lli);
238:   dw_gdma_ll_channel_enable(dev, ESP_MIPI_DSI_DMA_CHAN, true);
