241: /****************************************************************************
242:  * Name: esp_mipi_dsi_dma_isr
243:  *
244:  * Description:
245:  *   DW-GDMA interrupt handler. On DMA_TFR_DONE, re-arm the link list so
246:  *   continuous framebuffer streaming continues while video is enabled.
247:  *
248:  * Input Parameters:
249:  *   irq     - IRQ number (unused)
250:  *   context - Interrupt context (unused)
251:  *   arg     - Pointer to struct esp_mipi_dsi_priv_s
252:  *
253:  * Returned Value:
254:  *   Zero (OK)
255:  *
256:  ****************************************************************************/
257: 
258: static int IRAM_ATTR esp_mipi_dsi_dma_isr(int irq, FAR void *context,
259:                                           FAR void *arg)
260: {
261:   FAR struct esp_mipi_dsi_priv_s *priv =
262:     (FAR struct esp_mipi_dsi_priv_s *)arg;
263:   FAR dw_gdma_dev_t *dev;
264:   irqstate_t flags;
265:   uint32_t status;
266: 
267:   UNUSED(irq);
268:   UNUSED(context);
269: 
270:   if (priv == NULL || priv->dw_hal.dev == NULL)
271:     {
272:       return OK;
273:     }
274: 
275:   dev = priv->dw_hal.dev;
276:   flags = spin_lock_irqsave(&priv->dmalock);
277:   status = dw_gdma_ll_channel_get_intr_status(dev, ESP_MIPI_DSI_DMA_CHAN);
278:   dw_gdma_ll_channel_clear_intr(dev, ESP_MIPI_DSI_DMA_CHAN, status);
279:   priv->dma_last_status = status;
280: 
281:   if ((status & DW_GDMA_LL_CHANNEL_EVENT_DMA_TFR_DONE) != 0 &&
282:       priv->dma_enabled)
283:     {
284:       priv->dma_last_amount = dw_gdma_ll_channel_get_trans_amount(
285:                                 dev, ESP_MIPI_DSI_DMA_CHAN);
286:       priv->dma_last_fifo = dw_gdma_ll_channel_get_fifo_remain(
287:                               dev, ESP_MIPI_DSI_DMA_CHAN);
288:       priv->dma_last_common = dw_gdma_ll_get_common_intr_status(dev);
289:       priv->dma_tfr_count++;
290:       esp_mipi_dsi_dma_restart(priv);
291:     }
292: 
293:   spin_unlock_irqrestore(&priv->dmalock, flags);
294:   return OK;
295: }
