379: /****************************************************************************
380:  * Name: esp_mipi_dsi_cache_writeback
381:  *
382:  * Description:
383:  *   Write a dirty framebuffer range back in bounded chunks.  Cache writeback
384:  *   masks interrupts, so keep each operation short enough for continuous I2S
385:  *   playback while LVGL updates a moving object.
386:  ****************************************************************************/
387: 
388: static int esp_mipi_dsi_cache_writeback(FAR void *addr, size_t len)
389: {
390:   FAR uint8_t *cursor = (FAR uint8_t *)addr;
391:   esp_err_t err;
392:   size_t total = len;
393:   size_t chunks = 0;
394:   size_t chunk;
395: 
396:   while (len > 0)
397:     {
398:       chunk = len > ESP_MIPI_DSI_CACHE_CHUNK ?
399:               ESP_MIPI_DSI_CACHE_CHUNK : len;
400:       err = esp_cache_msync(cursor, chunk,
401:                             ESP_CACHE_MSYNC_FLAG_DIR_C2M |
402:                             ESP_CACHE_MSYNC_FLAG_UNALIGNED);
403:       if (err != ESP_OK)
404:         {
405:           return -EIO;
406:         }
407: 
408:       cursor += chunk;
409:       len -= chunk;
410:       chunks++;
411:     }
412: 
413:   vinfo("esp_mipi_dsi: cache writeback %zu bytes in %zu chunks\n",
414:         total, chunks);
415:   return OK;
416: }
