"}, {"type": "input_text", "text": "1: /****************************************************************************
2:  * boards/espressif/esp32p4/esp32p4-function-ev-board/src/esp32p4_display.c
3:  *
4:  * Simple Boot display bring-up for the 7" 1024x600 MIPI-DSI panel
5:  * (EK79007-class driver IC on the LCD adapter board).
6:  *
7:  * Sequence: power DPHY LDO -> DSI host init (2 lanes @900Mbps) -> panel
8:  * hard reset (GPIO27) -> vendor init cmds over LP DCS -> DPI timing ->
9:  * framebuffer (PSRAM) bind -> video start -> backlight (GPIO26).
10:  ****************************************************************************/
11: 
12: #include <nuttx/config.h>
13: 
14: #include <stdio.h>
15: #include <stdlib.h>
16: #include <string.h>
17: 
18: #include <nuttx/video/mipi_dsi.h>
19: #include <nuttx/video/fb.h>
20: #include <nuttx/signal.h>
21: #include <nuttx/kmalloc.h>
22: 
23: #include "esp_mipi_dsi.h"
24: #include "esp_ldo.h"
25: #include "esp_gpio.h"
26: 
27: #define LCD_RST_GPIO       27
28: #define LCD_BL_GPIO        26
29: 
30: #define FB_W               1024
31: #define FB_H               600
32: #define FB_BPP             16
33: #define FB_BYTES_PER_PIXEL (FB_BPP / 8)
34: #define FB_SIZE            (FB_W * FB_H * FB_BPP / 8)
35: 
36: #if defined(CONFIG_ESPRESSIF_SIMPLE_BOOT) && \
37:     !defined(CONFIG_ESP32P4_SELECTS_REV_LESS_V3)
38: extern int ets_printf(const char *fmt, ...);
39: #  define lcd_progress(s) ets_printf(s)
40: #else
41: #  define lcd_progress(s)
42: #endif
43: 
44: static FAR uint8_t *g_fb;
45: static volatile bool g_ready;
46: static uint32_t g_update_count;
47: 
48: /* EK79007 vendor registers */
49: #define EK79007_PAD_CONTROL 0xB2
50: #define EK79007_DSI_2_LANE  0x10
51: #define EK79007_CMD_SLPOUT  0x11
52: #define EK79007_CMD_DISPON  0x29
53: #define EK79007_CMD_COLMOD  0x3a
54: #define EK79007_COLMOD_16BPP 0x55
55: 
56: static const uint8_t g_ek79007_init[][2] =
57: {
58:     {0x80, 0x8B}, {0x81, 0x78}, {0x82, 0x84}, {0x83, 0x88},
59:     {0x84, 0xA8}, {0x85, 0xE3}, {0x86, 0x88},
60: };
61: 
62: static int ek79007_dcs_write(FAR struct mipi_dsi_device *dev, uint8_t cmd,
63:                              FAR const void *data, size_t len)
64: {
65:   ssize_t ret;
66: 
67:   ret = mipi_dsi_dcs_write(dev, cmd, data, len);
68:   if (ret < 0)
69:     {
70:       printf("DISP: DCS 0x%02x failed -> %ld\n", cmd, (long)ret);
71:       return (int)ret;
72:     }
73: 
74:   return OK;
75: }
