77: /****************************************************************************
78:  * Name: esp32p4_display_init
79:  ****************************************************************************/
80: 
81: int esp32p4_display_init(void)
82: {
83:   struct esp_mipi_dsi_bus_config_s bus;
84:   struct esp_mipi_dsi_dpi_config_s dpi;
85:   struct mipi_dsi_device *dev;
86:   struct esp_ldo_config_t phy_ldo;
87:   uint8_t lane_cmd;
88:   uint8_t pixel_format;
89:   uint8_t lane_readback;
90:   uint8_t power_mode;
91:   ssize_t read_ret;
92:   FAR uint8_t *fb = NULL;
93:   FAR uint16_t *fb16;
94:   unsigned int i;
95:   uint32_t dma_frames;
96:   uint32_t dma_status;
97:   uint32_t bridge_status;
98:   uint32_t lane_mbps_x100;
99:   uint32_t dpi_expect_mhz_x100;
100:   uint32_t dpi_real_mhz_x100;
101:   uint32_t host_int_st0;
102:   uint32_t host_int_st1;
103:   uint32_t host_vid_pkt_status;
104:   uint32_t host_phy_status;
105:   uint32_t host_color_coding;
106:   struct esp_mipi_dsi_timing_diagnostics_s timing_diag;
107:   struct esp_mipi_dsi_dma_diagnostics_s dma_diag;
108:   int ret;
109: 
110:   if (g_ready)
111:     {
112:       return OK;
113:     }
114: 
115:   lcd_progress("L0\n");
116: 
117:   /* A cold-powered panel needs its control pins in a deterministic state
118:    * before the DPHY and DSI host are enabled.  Keep both the backlight and
119:    * the active-low reset asserted throughout host initialization. */
120: 
121:   esp_configgpio(LCD_BL_GPIO, OUTPUT);
122:   esp_gpiowrite(LCD_BL_GPIO, false);
123:   esp_configgpio(LCD_RST_GPIO, OUTPUT);
124:   esp_gpiowrite(LCD_RST_GPIO, false);
125: 
126:   /* 1. VDD_MIPI_DPHY from on-chip LDO channel 3 @ 2.5V */
127: 
128:   phy_ldo.chan_id    = 3;
129:   phy_ldo.voltage_mv = 2500;
130:   phy_ldo.handler    = NULL;
131: 
132:   ret = esp_ldo_channel_acquire(&phy_ldo);
133:   printf("DISP: dphy ldo ch3@2.5V -> %d\n", ret);
134:   if (ret != OK)
135:     {
136:       return ret;
137:     }
138: 
139:   nxsig_usleep(20 * 1000);
140: 
141:   /* 2. DSI host: match Espressif's EK79007 component reference profile
142:    * exactly.  Keeping the lane rate, pixel clock, and blanking timings as
143:    * one coherent profile is essential: mixing profiles makes a cold-started
144:    * panel lock onto an incomplete active window. */
145: 
146:   memset(&bus, 0, sizeof(bus));
147:   bus.num_data_lanes     = 2;
148:   bus.lane_bit_rate_mbps = 900;
149: 
150:   ret = esp_mipi_dsi_initialize(&bus);
151:   printf("DISP: dsi host init -> %d\n", ret);
152:   if (ret != OK)
153:     {
154:       return ret;
155:     }
156: 
157:   dev = mipi_dsi_device_register(esp_mipi_dsi_host_get(), "ek79007", 0);
158:   if (dev == NULL)
159:     {
160:       printf("DISP: device register failed\n");
161:       return -ENODEV;
162:     }
163: 
164:   dev->lanes     = 2;
165:   dev->format    = MIPI_DSI_FMT_RGB565;
166:   dev->mode_flags = MIPI_DSI_MODE_VIDEO | MIPI_DSI_MODE_LPM;
167: 
168:   ret = mipi_dsi_attach(dev);
169:   printf("DISP: panel attach -> %d\n", ret);
170:   if (ret != OK)
171:     {
172:       return ret;
173:     }
174: 
175:   lcd_progress("L1\n");
176: 
177:   /* 3. Panel hardware reset, active low */
178: 
179:   nxsig_usleep(20 * 1000);
180:   esp_gpiowrite(LCD_RST_GPIO, true);
181:   nxsig_usleep(120 * 1000);
182: 
183:   /* 4. Vendor init sequence over LP DCS */
184: 
185:   lane_cmd = EK79007_DSI_2_LANE;
186:   ret = ek79007_dcs_write(dev, EK79007_PAD_CONTROL, &lane_cmd, 1);
187:   if (ret != OK)
188:     {
189:       return ret;
190:     }
191: 
192:   for (i = 0; i < sizeof(g_ek79007_init) / sizeof(g_ek79007_init[0]); i++)
193:     {
194:       ret = ek79007_dcs_write(dev, g_ek79007_init[i][0],
195:                               &g_ek79007_init[i][1], 1);
196:       if (ret != OK)
197:         {
198:           return ret;
199:         }
200:     }
201: 
202:   /* Revision 1.x has one shared bridge raw pixel type, so use RGB565 from
203:    * PSRAM through the DSI Host and tell the panel to decode 16 bpp too. */
204: 
205:   pixel_format = EK79007_COLMOD_16BPP;
206:   ret = ek79007_dcs_write(dev, EK79007_CMD_COLMOD, &pixel_format, 1);
207:   if (ret != OK)
208:     {
209:       return ret;
210:     }
211: 
212:   ret = ek79007_dcs_write(dev, EK79007_CMD_SLPOUT, NULL, 0);
213:   if (ret != OK)
214:     {
215:       return ret;
216:     }
217: 
218:   nxsig_usleep(120 * 1000);
219:   ret = ek79007_dcs_write(dev, EK79007_CMD_DISPON, NULL, 0);
220:   if (ret != OK)
221:     {
222:       return ret;
223:     }
224: 
225:   nxsig_usleep(20 * 1000);
226:   lane_readback = 0;
227:   read_ret = mipi_dsi_dcs_read(dev, EK79007_PAD_CONTROL,
228:                                &lane_readback, 1);
229:   printf("DISP: panel B2 read -> %ld value=%02x\n",
230:          (long)read_ret, lane_readback);
231: 
232:   power_mode = 0;
233:   read_ret = mipi_dsi_dcs_read(dev, 0x0a, &power_mode, 1);
234:   printf("DISP: panel power mode -> %ld value=%02x\n",
235:          (long)read_ret, power_mode);
236:   printf("DISP: panel init done\n");
237: 
238:   /* 5. DPI timing from the official EK79007 1024x600@60 profile. */
239: 
240:   memset(&dpi, 0, sizeof(dpi));
241:   dpi.h_res              = FB_W;
242:   dpi.v_res              = FB_H;
243:   dpi.hsync_pulse_width  = 10;
244:   dpi.hsync_back_porch   = 160;
245:   dpi.hsync_front_porch  = 160;
246:   dpi.vsync_pulse_width  = 1;
247:   dpi.vsync_back_porch   = 23;
248:   dpi.vsync_front_porch  = 12;
249:   /* Revision 1.x cannot run this board's 32 MiB PSRAM reliably at 200 MHz.
250:    * Its 80 MHz memory setting is paired with a 24 MHz pixel clock to halve
251:    * scanout bandwidth while preserving the complete 1024x600 active area.
252:    * This 30 Hz mode has been verified physically to fill the panel. */
253: 
254: #ifdef CONFIG_ESP32P4_SELECTS_REV_LESS_V3
255:   /* Revision 1.x boards pair the same official blanking windows with a
256:    * lower pixel clock because their 80 MHz PSRAM setup cannot sustain the
257:    * full scanout bandwidth.  This verified 30 Hz mode still addresses the
258:    * complete 1024x600 active area. */
259:   dpi.dpi_clock_freq_mhz = 24;
260: #else
261:   /* Official ESP32-P4 EK79007 1024x600@60Hz pixel clock. */
262:   dpi.dpi_clock_freq_mhz = 52;
263: #endif
264:   dpi.virtual_channel    = 0;
265:   dpi.format             = MIPI_DSI_FMT_RGB565;
266: 
267:   ret = esp_mipi_dsi_configure_dpi(&dpi);
268:   printf("DISP: dpi config -> %d\n", ret);
269:   if (ret != OK)
270:     {
271:       return ret;
272:     }
273: 
274:   /* 6. Select the pixel source.  The host pattern is the same isolation
275:    * test provided by the ESP-IDF DPI panel driver. */
276: 
277: #ifdef CONFIG_ESPRESSIF_MIPI_DSI_TEST_PATTERN
278:   ret = esp_mipi_dsi_set_test_pattern(true);
279:   printf("DISP: host pattern (no PSRAM/DMA) -> %d\n", ret);
280:   if (ret != OK)
281:     {
282:       return ret;
283:     }
284: #else
285:   /* Framebuffer from PSRAM-backed heap */
286: 
287:   fb = kmm_memalign(64, FB_SIZE);
288:   if (fb == NULL)
289:     {
290:       printf("DISP: cannot allocate %u-byte RGB565 framebuffer\n",
291:              (unsigned int)FB_SIZE);
292:       return -ENOMEM;
293:     }
294: 
295:   fb16 = (FAR uint16_t *)fb;
296:   printf("DISP: RGB565 framebuffer @%p size=%u\n", fb,
297:          (unsigned int)FB_SIZE);
298: 
299:   /* Eight full-height RGB565 bars make line width, channel order, and the
300:    * amount of active image immediately identifiable on the physical LCD. */
301: 
302:   static const uint16_t bars[8] =
303:   {
304:     0x0000, 0xf800, 0x07e0, 0x001f,
305:     0x07ff, 0xf81f, 0xffe0, 0xffff
306:   };
307: 
308:   for (i = 0; i < FB_W * FB_H; i++)
309:     {
310:       unsigned int bar = (i % FB_W) / (FB_W / 8);
311:       fb16[i] = bars[bar];
312:     }
313: 
314: #ifdef CONFIG_ESPRESSIF_MIPI_DSI_FIXED_SOURCE_TEST
315:   /* A fixed-source DMA repeats these four RGB565 red pixels for the entire
316:    * transfer.  A full red panel proves bridge/Host framing independently of
317:    * sequential PSRAM access. */
318: 
319:   fb16[0] = 0xf800;
320:   fb16[1] = 0xf800;
321:   fb16[2] = 0xf800;
322:   fb16[3] = 0xf800;
323: #endif
324: 
325:   ret = esp_mipi_dsi_bind_framebuffer(fb, FB_SIZE, FB_W, FB_H, FB_BPP);
326:   printf("DISP: fb bind -> %d\n", ret);
327:   if (ret != OK)
328:     {
329:       kmm_free(fb);
330:       return ret;
331:     }
332: 
333:   ret = esp_mipi_dsi_flush_framebuffer(fb, FB_SIZE);
334:   printf("DISP: fb flush -> %d\n", ret);
335:   if (ret != OK)
336:     {
337:       return ret;
338:     }
339: 
340:   lcd_progress("L2\n");
341: #endif
342: 
343:   /* 7. Go live, then backlight on */
344: 
345:   ret = esp_mipi_dsi_video_start();
346:   printf("DISP: video start -> %d\n", ret);
347:   if (ret != OK)
348:     {
349:       return ret;
350:     }
351: 
352:   lcd_progress("L3\n");
353: 
354:   esp_configgpio(LCD_BL_GPIO, OUTPUT);
355:   esp_gpiowrite(LCD_BL_GPIO, true);
356:   printf("DISP: backlight on after video start\n");
357: 
358:   nxsig_usleep(250 * 1000);
359:   ret = esp_mipi_dsi_get_diagnostics(&dma_frames, &dma_status,
360:                                      &bridge_status, &lane_mbps_x100,
361:                                      &dpi_expect_mhz_x100,
362:                                      &dpi_real_mhz_x100, &host_int_st0,
363:                                      &host_int_st1, &host_vid_pkt_status,
364:                                      &host_phy_status, &host_color_coding);
365:   printf("DISP: 250ms frames=%lu dma=%08lx bridge=%08lx "
366:          "lane=%lu.%02luMbps dpi=%lu.%02lu/%lu.%02luMHz -> %d\n",
367:          (unsigned long)dma_frames, (unsigned long)dma_status,
368:          (unsigned long)bridge_status,
369:          (unsigned long)(lane_mbps_x100 / 100),
370:          (unsigned long)(lane_mbps_x100 % 100),
371:          (unsigned long)(dpi_real_mhz_x100 / 100),
372:          (unsigned long)(dpi_real_mhz_x100 % 100),
373:          (unsigned long)(dpi_expect_mhz_x100 / 100),
374:          (unsigned long)(dpi_expect_mhz_x100 % 100), ret);
375:   printf("DISP: host int0=%08lx int1=%08lx vid=%08lx phy=%08lx color=%08lx\n",
376:          (unsigned long)host_int_st0, (unsigned long)host_int_st1,
377:          (unsigned long)host_vid_pkt_status, (unsigned long)host_phy_status,
378:          (unsigned long)host_color_coding);
379:   lcd_progress("L4\n");
380: 
381:   ret = esp_mipi_dsi_get_timing_diagnostics(&timing_diag);
382:   printf("DISP: brg words=%lu fifo=%08lx pix=%08lx "
383:          "h=%lu/%lu/%lu/%lu v=%lu/%lu/%lu/%lu -> %d\n",
384:          (unsigned long)timing_diag.bridge_raw_words,
385:          (unsigned long)timing_diag.bridge_fifo_status,
386:          (unsigned long)timing_diag.bridge_pixel_type,
387:          (unsigned long)timing_diag.bridge_hactive,
388:          (unsigned long)timing_diag.bridge_htotal,
389:          (unsigned long)timing_diag.bridge_hsync,
390:          (unsigned long)timing_diag.bridge_hback_porch,
391:          (unsigned long)timing_diag.bridge_vactive,
392:          (unsigned long)timing_diag.bridge_vtotal,
393:          (unsigned long)timing_diag.bridge_vsync,
394:          (unsigned long)timing_diag.bridge_vback_porch, ret);
395:   printf("DISP: host cfg pkt=%lu h=%lu/%lu/%lu "
396:          "v=%lu/%lu/%lu/%lu\n",
397:          (unsigned long)timing_diag.host_packet_pixels,
398:          (unsigned long)timing_diag.host_hsync_time,
399:          (unsigned long)timing_diag.host_hback_porch_time,
400:          (unsigned long)timing_diag.host_hline_time,
401:          (unsigned long)timing_diag.host_vsync_lines,
402:          (unsigned long)timing_diag.host_vback_porch_lines,
403:          (unsigned long)timing_diag.host_vfront_porch_lines,
404:          (unsigned long)timing_diag.host_vactive_lines);
405: 
406:   nxsig_usleep(5 * 1000 * 1000);
407:   ret = esp_mipi_dsi_get_diagnostics(&dma_frames, &dma_status,
408:                                      &bridge_status, &lane_mbps_x100,
409:                                      &dpi_expect_mhz_x100,
410:                                      &dpi_real_mhz_x100, &host_int_st0,
411:                                      &host_int_st1, &host_vid_pkt_status,
412:                                      &host_phy_status, &host_color_coding);
413:   printf("DISP: 5s frames=%lu dma=%08lx bridge=%08lx "
414:          "host=%08lx/%08lx vid=%08lx phy=%08lx -> %d\n",
415:          (unsigned long)dma_frames, (unsigned long)dma_status,
416:          (unsigned long)bridge_status, (unsigned long)host_int_st0,
417:          (unsigned long)host_int_st1,
418:          (unsigned long)host_vid_pkt_status,
419:          (unsigned long)host_phy_status, ret);
420: 
